import java.util.Scanner;

class Cat {
    static int count = 0;
    String name;

    Cat(String name) {
        this.name = name;
        count = count + 1;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Cat[] cats = new Cat[n];
        for (int i = 0; i < n; i++) {
            cats[i] = new Cat("{cat}" + (i + 1));
        }
        System.out.println("一共出生了 " + Cat.count + " 只");
        System.out.println("第一只叫 " + cats[0].name);
    }
}
